public class Foo {
    void m(java.util.Iterator<String> it) {
        String s;
        while (it.hasNext()) {
            s = it.next();
            if (s.isEmpty()) {
                continue;
            }
            if (s.equals("end")) {
                break;
            }
        }
    }
}

